-- Phase M hardening: every registered agent gets bounded messaging/sandbox permissions and durable ordered messages.
insert into public.agent_permissions(agent_id,permission,allowed,requires_approval) select id,'agent.message.send',true,false from public.agents on conflict(agent_id,permission) do nothing;
insert into public.agent_permissions(agent_id,permission,allowed,requires_approval) select id,'sandbox.open',true,false from public.agents on conflict(agent_id,permission) do nothing;
create or replace function public.append_agent_message(p_task_id uuid,p_run_id uuid,p_from_agent text,p_to_agent text,p_message_type text,p_payload jsonb default '{}'::jsonb,p_correlation_id uuid default null) returns public.agent_messages language plpgsql security definer set search_path=public as $$ declare n integer; row public.agent_messages; begin perform 1 from public.tasks where id=p_task_id for update; if not found then raise exception 'Task not found'; end if; select coalesce(max(sequence),0)+1 into n from public.agent_messages where task_id=p_task_id; insert into public.agent_messages(task_id,run_id,from_agent,to_agent,message_type,payload,sequence,correlation_id) values(p_task_id,p_run_id,p_from_agent,p_to_agent,p_message_type,coalesce(p_payload,'{}'::jsonb),n,p_correlation_id) returning * into row; return row; end; $$;
revoke all on function public.append_agent_message(uuid,uuid,text,text,text,jsonb,uuid) from public,anon,authenticated; grant execute on function public.append_agent_message(uuid,uuid,text,text,text,jsonb,uuid) to service_role;
